class Solution:
    def largestIntegerWithDigitSum(self, n, s):
        if s > 9 * n:
            return -1
        digits = []
        for _ in range(n):
            d = min(9, s)
            digits.append(d)
            s -= d
        return int(''.join(map(str, digits)))

