class Solution {
    public long largestIntegerWithDigitSum(int n, int s) {
        if (s > 9 * n) return -1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int d = Math.min(9, s);
            sb.append(d);
            s -= d;
        }
        return Long.parseLong(sb.toString());
    }
}

