class Solution {
    public long largestIntegerWithDigitSum(int n, int s) {
        int q = s / 9, r = s % 9;
        String t = (r > 0 ? Integer.toString(r) : "") + "9".repeat(q);
        if (t.length() > n) return -1;
        return t.isEmpty() ? 0 : Long.parseLong(t);
    }
}

